/** Durable, single-run-at-a-time queue for the factory supervisor. */
import { createHash, randomUUID } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import { normalizeBrief, BriefError } from './brief.mjs';

const projectPattern = /^[a-z0-9][a-z0-9-]{0,39}$/;

export class QueueError extends Error {}

export function openQueue(path) {
  const db = new DatabaseSync(path);
  db.exec('PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;');
  db.exec(`CREATE TABLE IF NOT EXISTS autonomy_jobs (
    job_id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE,
    project_id TEXT NOT NULL, request TEXT NOT NULL, reference_path TEXT, brief_json TEXT,
    input_hash TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
    not_before_ms INTEGER NOT NULL DEFAULT 0, error_code TEXT, error TEXT,
    started_at TEXT, finished_at TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )`);
  const columns = new Set(db.prepare('PRAGMA table_info(autonomy_jobs)').all().map(row => row.name));
  if (!columns.has('brief_json')) db.exec('ALTER TABLE autonomy_jobs ADD COLUMN brief_json TEXT');
  return db;
}

export function enqueue(db, { projectId, request, referencePath = null, idempotencyKey, brief = null }) {
  if (!projectPattern.test(projectId ?? '') || typeof request !== 'string'
    || !request.trim() || request.length > 10_000
    || typeof idempotencyKey !== 'string' || !/^[A-Za-z0-9_-]{8,100}$/.test(idempotencyKey)
    || (referencePath !== null && (typeof referencePath !== 'string' || !referencePath.startsWith('/')))) {
    throw new QueueError('Invalid project, request, reference path, or idempotency key');
  }
  const normalizedRequest = request.trim();
  let normalizedBrief = null;
  try {
    if (brief !== null) normalizedBrief = normalizeBrief(brief, normalizedRequest, referencePath !== null);
  } catch (error) {
    if (error instanceof BriefError) throw new QueueError(error.message);
    throw error;
  }
  const input = [projectId, normalizedRequest, referencePath];
  if (normalizedBrief) input.push(normalizedBrief);
  const hash = createHash('sha256').update(JSON.stringify(input)).digest('hex');
  const previous = db.prepare('SELECT * FROM autonomy_jobs WHERE idempotency_key = ?').get(idempotencyKey);
  if (previous) {
    if (previous.input_hash !== hash) throw new QueueError('Idempotency key belongs to a different request');
    return previous;
  }
  const active = db.prepare(`SELECT job_id FROM autonomy_jobs WHERE project_id = ?
    AND status IN ('queued', 'running', 'blocked') LIMIT 1`).get(projectId);
  if (active) throw new QueueError(`Project already has an unfinished job: ${active.job_id}`);
  const jobId = randomUUID();
  db.prepare(`INSERT INTO autonomy_jobs
    (job_id, idempotency_key, project_id, request, reference_path, brief_json, input_hash, status)
    VALUES (?, ?, ?, ?, ?, ?, ?, 'queued')`).run(jobId, idempotencyKey, projectId,
    normalizedRequest, referencePath, normalizedBrief ? JSON.stringify(normalizedBrief) : null, hash);
  return getJob(db, jobId);
}

export function getJob(db, jobId) {
  return db.prepare('SELECT * FROM autonomy_jobs WHERE job_id = ?').get(jobId) ?? null;
}

export function listJobs(db, limit = 30) {
  return db.prepare('SELECT * FROM autonomy_jobs ORDER BY created_at DESC, rowid DESC LIMIT ?')
    .all(Math.max(1, Math.min(100, limit)));
}

export function recoverInterrupted(db) {
  return db.prepare(`UPDATE autonomy_jobs SET status = 'queued', error_code = 'interrupted',
    error = 'Supervisor restarted; resuming from saved factory state',
    updated_at = CURRENT_TIMESTAMP WHERE status = 'running'`).run().changes;
}

export function claimNext(db, now = Date.now()) {
  const job = db.prepare(`SELECT * FROM autonomy_jobs WHERE status = 'queued'
    AND not_before_ms <= ? ORDER BY created_at, rowid LIMIT 1`).get(now);
  if (!job) return null;
  const changed = db.prepare(`UPDATE autonomy_jobs SET status = 'running', attempts = attempts + 1,
    started_at = CURRENT_TIMESTAMP, error_code = NULL, error = NULL,
    updated_at = CURRENT_TIMESTAMP WHERE job_id = ? AND status = 'queued'`).run(job.job_id).changes;
  return changed ? getJob(db, job.job_id) : null;
}

export function finishJob(db, jobId, { status, code = null, error = null, retryAfterMs = 0 }) {
  if (!['complete', 'blocked', 'failed', 'queued'].includes(status)) throw new QueueError('Invalid job status');
  const job = getJob(db, jobId);
  if (!job || job.status !== 'running') throw new QueueError('Only a running job can be finished');
  db.prepare(`UPDATE autonomy_jobs SET status = ?, error_code = ?, error = ?,
    not_before_ms = ?, finished_at = ?, updated_at = CURRENT_TIMESTAMP WHERE job_id = ?`)
    .run(status, code, error, status === 'queued' ? Date.now() + retryAfterMs : 0,
      status === 'queued' ? null : new Date().toISOString(), jobId);
  return getJob(db, jobId);
}

export function resumeBlocked(db, jobId) {
  const changed = db.prepare(`UPDATE autonomy_jobs SET status = 'queued', not_before_ms = 0,
    error_code = NULL, error = NULL, finished_at = NULL, updated_at = CURRENT_TIMESTAMP
    WHERE job_id = ? AND (status IN ('blocked', 'failed')
      OR (status = 'queued' AND error_code = 'usage_limit_exceeded'))`).run(jobId).changes;
  if (!changed) throw new QueueError('Job is not blocked, failed, or waiting for credits');
  return getJob(db, jobId);
}

item.aggregated_output:
Explain provides human-readable context about sessions, commits, and checkpoints.

Use this command to understand what happened during agent-driven development,
either for self-review or to understand a teammate's work.

By default, shows checkpoints on the current branch. Pass a checkpoint ID or
commit SHA as a positional argument to explain a specific item, or use flags.

Viewing specific items:
  entire checkpoint explain <id-or-sha>           Auto-detects checkpoint ID or commit SHA
  entire checkpoint explain --checkpoint <id>     Force interpretation as checkpoint ID
  entire checkpoint explain --commit <ref>        Force interpretation as commit ref

Checkpoints in another repo:
  entire checkpoint explain <id> --repo gh/owner/name
  entire checkpoint explain <id> --repo et/project/repo
                 Explain a checkpoint owned by another repository — the
                 drill-down for a cross-repo 'entire search' hit. Reads it from
                 that repo's Entire API; nothing is written to this repo.
                 Needs a full checkpoint ID (positional or --checkpoint) and a
                 checkpoint that has been pushed.

Filtering the list view:
  --session      Filter checkpoints by session ID (or prefix)

Output verbosity levels (when explaining a specific item):
  Default:         Detailed view with scoped prompts (ID, session, tokens, intent, prompts, files)
  --short          Summary only (ID, session, timestamp, tokens, intent)
  --full           Parsed full transcript (all prompts/responses from entire session)
  --raw-transcript Raw transcript file (JSONL format)

Machine-readable export modes (additive surface for external consumers):
  --json           Metadata-only JSON. Lists checkpoints when no target is given;
                   emits a single checkpoint envelope when a target is supplied.
                   Transcript bytes are NEVER embedded in the JSON envelope.
  --transcript     Stream stored checkpoint transcript bytes (JSONL) to stdout
                   for the selected session. Same bytes as --raw-transcript
                   while checkpoints v1 is the checkpoint store.
  --session-index  Pick a session within a multi-session checkpoint (0-based).
                   Defaults to the latest session. Only meaningful with
                   --transcript or --raw-transcript.
  --limit          Cap the number of checkpoints returned by the list view.
                   Defaults to 100. When the cap is hit, a stderr note
                   says how many were skipped. Only meaningful with --json.

Summary generation:
  --generate    Generate an AI summary for the checkpoint. This is the only
                part of this command that writes: it stores the summary on the
                checkpoint and spends tokens with the configured summary
                provider. Every other mode only reads.
  --force       Regenerate even if a summary already exists (requires --generate)

Performance options:
  --search-all  Remove branch/depth limits when searching for commits (may be slow)

Checkpoint detail view shows:
  - Author of the checkpoint
  - Associated git commits that reference the checkpoint
  - Prompts and responses from the session

Note: --session filters the list view; the positional arg, --commit, and --checkpoint are mutually exclusive.

Usage:
  entire checkpoint explain [checkpoint-id | commit-sha] [flags]

Flags:
  -c, --checkpoint string             Explain a specific checkpoint (ID or prefix)
      --commit string                 Explain a specific commit (SHA or ref, "commit-ish")
      --force                         Regenerate summary even if one already exists (requires --generate)
      --full                          Show full parsed transcript (all prompts/responses)
      --generate                      Generate an AI summary for the checkpoint
  -h, --help                          help for explain
      --insecure-http-auth            Allow plain-HTTP auth for --repo (local dev only)
      --json                          Output metadata as JSON (no transcript bytes)
      --limit int                     Cap the list view at N checkpoints (default: 100). Only meaningful with --json.
      --no-pager                      Disable pager output
      --raw-transcript                Show raw transcript file (JSONL format)
      --repo string                   Explain a checkpoint owned by another repo (gh/owner/name, et/project/repo, entire://<host>/gh/<owner>/<repo>, or entire://<host>/et/<project>/<repo>), read from that repo's Entire API
      --search-all                    Search all commits (no branch/depth limit, may be slow)
      --session string                Filter checkpoints by session ID (or prefix)
      --session-index int             Session index within a multi-session checkpoint (0-based, defaults to latest) (default -1)
  -s, --short                         Show summary only (omit prompts and files)
      --summary-timeout-seconds int   Hard deadline in seconds for --generate summary generation; overrides summary_timeout_seconds setting. 0 = use setting; if setting is also unset or 0, no automatic deadline applies.
      --transcript                    Stream stored checkpoint transcript bytes to stdout

Global Flags:
      --context name   Act as this saved login name for this command only — including the git and agent processes it spawns — instead of the active context (entire auth contexts lists them)
